column3:
@"std/view"
views: {&: $.view.Figure} & {
  a: {kind: tree, relation: dependsOn, roots: ["$.x"], at: "$.y", maxRows: 9, as: svg, out: "a.svg"}
  b: {kind: graph, relations: ["dependsOn"], groupBy: owner, label: name, as: dot, out: "b.dot"}
  c: {kind: layer, groupBy: layer, layers: ["app"], edges: all, out: "c.txt"}
  d: {kind: sets, sets: "$.roles", member: grants, universe: "$.perms", minDegree: 1, maxCols: 2, out: "d.txt"}
  e: {kind: layers, minSize: 1, out: "e.txt"}
  g: {kind: ladder, at: "$.z", out: "g.mmd"}
}
